import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"4.3 手机查看、审批与接管","description":"手机只保留关键动作和短期权限，丢失后可立即撤销。","frontmatter":{"title":"4.3 手机查看、审批与接管","description":"手机只保留关键动作和短期权限，丢失后可立即撤销。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-4/4-3.md","filePath":"delivery/stage-4/4-3.md","lastUpdated":1793859143000}'),r={name:"delivery/stage-4/4-3.md"};function o(s,e,n,d,_,c){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="_4-3-手机查看、审批与接管" tabindex="-1">4.3 手机查看、审批与接管 <a class="header-anchor" href="#_4-3-手机查看、审批与接管" aria-label="Permalink to &quot;4.3 手机查看、审批与接管&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>让用户在手机上完成最关键的查看、审批和接管，同时保证手机丢失后可以立即撤销，不把长期主权限放在手机上。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>提供手机网页入口，支持查看今日任务、需要你处理的事项和产物。</li><li>审批页展示真实对象、内容、影响和是否可撤销，关键操作要求再次确认。</li><li>支持在手机上暂停、接管和终止任务，接管时立即停止自动操作。</li><li>用短期配对码建立连接，手机不保存长期主权限；推送内容不包含敏感正文。</li><li>手机丢失时可以立即撤销，撤销后不能继续审批、接管或查看任务。</li><li>断网时只提供只读和明确的状态提示，恢复后再同步。</li></ol>',5)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
